#!/bin/sh
# Suíte do Banco (tests/banco-revisao/test_review_bank.sql, inclusive as partes da rotina automática) com a 096 aplicada
# por cima: o aluno ligado a UMA conta e a rotina precisam continuar funcionando igual. Cópia de
# tests/banco-revisao/run_local.sh + stub de Turmas + 096 (aplicada depois da 100, como no Staging/produção).
set -e
D="$(cd "$(dirname "$0")/../.." && pwd)"
pg_ctlcluster 16 main start 2>/dev/null || true; sleep 2
su postgres -c "psql -q -c 'drop database if exists banco96' -c 'create database banco96'"
su postgres -c "psql -q -d banco96 -c \"do \\\$\\\$ begin if not exists (select 1 from pg_roles where rolname='service_role') then create role service_role nologin bypassrls; end if; end \\\$\\\$\""
su postgres -c "psql -q -v ON_ERROR_STOP=1 -d banco96 -f $D/tests/papeis-permissoes/local_stub_schema.sql -f $D/tests/papeis-permissoes/stub_076.sql -f $D/shared/supabase_migrations/075_account_roles_and_permissions.sql -f $D/shared/supabase_migrations/076_teacher_role_policies.sql -f $D/tests/banco-revisao/stub_review_bank.sql -f $D/tests/banco-revisao/stub_agent_inbox.sql -f $D/shared/supabase_migrations/081_review_bank.sql -f $D/shared/supabase_migrations/082_review_bank_roster.sql -f $D/shared/supabase_migrations/083_review_bank_schedule.sql -f $D/shared/supabase_migrations/084_review_bank_import_keys.sql -f $D/shared/supabase_migrations/089_review_bank_agent.sql -f $D/shared/supabase_migrations/090_review_bank_agent_deck_fix.sql -f $D/shared/supabase_migrations/097_review_bank_agent_inbox.sql -f $D/shared/supabase_migrations/098_review_bank_agent_inbox_dispatch_error.sql -f $D/shared/supabase_migrations/099_review_bank_agent_state_light.sql -f $D/shared/supabase_migrations/100_review_bank_agent_other_students.sql -f $D/tests/banco-revisao-turmas/stub_087_094.sql -f $D/shared/supabase_migrations/096_review_bank_classrooms.sql"
# idempotência: reaplicar não pode falhar
su postgres -c "psql -q -v ON_ERROR_STOP=1 -d banco96 -f $D/shared/supabase_migrations/081_review_bank.sql -f $D/shared/supabase_migrations/082_review_bank_roster.sql -f $D/shared/supabase_migrations/083_review_bank_schedule.sql -f $D/shared/supabase_migrations/084_review_bank_import_keys.sql -f $D/shared/supabase_migrations/085_review_bank_sensitive.sql -f $D/shared/supabase_migrations/089_review_bank_agent.sql -f $D/shared/supabase_migrations/090_review_bank_agent_deck_fix.sql -f $D/shared/supabase_migrations/097_review_bank_agent_inbox.sql -f $D/shared/supabase_migrations/098_review_bank_agent_inbox_dispatch_error.sql -f $D/shared/supabase_migrations/099_review_bank_agent_state_light.sql -f $D/shared/supabase_migrations/100_review_bank_agent_other_students.sql -f $D/shared/supabase_migrations/096_review_bank_classrooms.sql"
su postgres -c "psql -q -d banco96 -c 'grant all on all tables in schema public to authenticated' -c 'grant usage on schema public to authenticated' -c 'grant all on all tables in schema public to service_role' -c 'grant usage on schema public to service_role'"
su postgres -c "psql -d banco96 -f $D/tests/banco-revisao/test_review_bank.sql" 2>&1 | grep -A12 "passed | failed"
